window.docContents[44].resolve({"/The-sharp-sub-Coulomb-commutator/#Fluctuations-of-Riesz-gases--The-sharp-sub-Coulomb-commutator--Whole-space-argument":{"contents":"At unit scale, for bounded compactly supported densities, split the force into high and low frequencies, then split the transport in the low-frequency term. This gives three contributions: high-frequency force, low-frequency force with low-frequency transport, and low-frequency force with high-frequency transport. The last is a particle sum minus a background integral; estimate these separately and add the three bounds.\n\n","context":"Fluctuations of Riesz gases\u0009The sharp sub-Coulomb commutator","header":"1.1. Whole-space argument","id":"/The-sharp-sub-Coulomb-commutator/#Fluctuations-of-Riesz-gases--The-sharp-sub-Coulomb-commutator--Whole-space-argument"}});